

select * from customer limit 20;
-- Q1.# What is the revenue generated by female and male costomer
select sum(purchase_amount) as total_revenue, gender from customer group by gender;

-- Q2. Which customer use the discount but still spent more than the average purchase amount.
select customer_id, purchase_amount from customer where discount_applied  = 'Yes'
and purchase_amount >= (select avg(purchase_amount) from customer);

