-- Q4 Compare the average purchase amounts btw standard and express shipping.
-- select shipping_type from customer;
select shipping_type, 
avg(purchase_amount) 
from customer where
shipping_type in ('Standard', 'Express')
group by shipping_type;

-- Q5. Do subcribers customer spend more ? Compare average spend and total revenue between subscribers and non subcribers.
-- select subscription_status, count(subscription_status) from customer
-- group by subscription_status;

select subscription_status,
count(customer_id) as total_customer, 
round(sum(purchase_amount),2) as total_revenue,
round(avg(purchase_amount),2) as avg_spend
from customer
group by subscription_status
order by total_revenue, avg_spend desc;

