-- Q7. Segment customer into new , Returning , and loyal based on
-- their total number of previous purchases and show how many times of each segment
with customer_type as (
	select customer_id, previous_purchases,
	case
	when previous_purchases = 1 then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
	else 'Loyal'
	end as customer_segment
	from customer
)
select customer_segment, count(*) as "number of customers"
from customer_type
group by customer_segment;

-- Q8 what are the 3 most purchased products in each category?
with items_counts as (
select category, 
item_purchased,
count(customer_id) as total_order,
dense_rank() over(partition by category order by count(customer_id) desc) as item_rank
from customer
group by category, item_purchased
)
select item_rank, category, item_purchased, total_order
from items_counts
where item_rank <=3;

-- Q9 are customers who are repeated buyers (more than  5previous purchases) also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from customer 
where previous_purchases > 5
group by subscription_Status;

-- 10 What is the revenue contribution of each groups?

select age_groups , sum(purchase_amount) as total_revenue
from customer
group by age_groups
order by total_revenue desc;